class FlowGraphScript_0_13;
FlowGraphScript_0_13* g_time_FlowGraphScript_0_13 = nullptr;

// Scene "main": graph of "hud" (object 13)
class FlowGraphScript_0_13 : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (ctx.scene != 0) return;
    // Live Debugger: nothing in this graph advances while the game is
    // stopped at a breakpoint (the loop's own pause covers the rest).
    if (livedbg::halted()) return;
    // Live Logic: while the editor has a patch for this graph, the
    // interpreter runs it instead of this compiled copy.
    if (livelogic::patched(0, 13)) return;
    if (ctx.sceneGeneration != generation) {
      // scene was (re)loaded - back to the initial state
      generation = ctx.sceneGeneration;
      frame = 0;
      started = false;
    }
    frame++;
    if (ctx.dynTextOn && ctx.dynTextOn[1])
      flowSetDynText(ctx, 1, std::string("Crystals: ") + flowNumText(ctx.saveValues[0]));
    if (ctx.dynTextOn && ctx.dynTextOn[2])
      flowSetDynText(ctx, 2, std::string("Deaths: ") + flowNumText((float)flowInt[0]));
    if (ctx.dynTextOn && ctx.dynTextOn[3])
      flowSetDynText(ctx, 3, std::string("Checkpoint: ") + std::string(&ctx.saveTexts[0 * SAVE_TEXT_LEN]));
    if (livedbg::forced(37)) {  // Live Debugger: fired from the editor
      livedbg::hit(37);
      livedbg::hit(38);
      ctx.dynTextRequest[1] = 1;
      ctx.dynTextDuration[1] = 0.0F;
      flowSetDynText(ctx, 1, std::string("Crystals: ") + flowNumText(ctx.saveValues[0]));
      livedbg::hit(39);
      ctx.dynTextRequest[2] = 1;
      ctx.dynTextDuration[2] = 0.0F;
      flowSetDynText(ctx, 2, std::string("Deaths: ") + flowNumText((float)flowInt[0]));
      livedbg::hit(40);
      ctx.dynTextRequest[3] = 1;
      ctx.dynTextDuration[3] = 0.0F;
      flowSetDynText(ctx, 3, std::string("Checkpoint: ") + std::string(&ctx.saveTexts[0 * SAVE_TEXT_LEN]));
    }
    if (!started) {
      started = true;
      livedbg::hit(37);
      livedbg::hit(38);
      ctx.dynTextRequest[1] = 1;
      ctx.dynTextDuration[1] = 0.0F;
      flowSetDynText(ctx, 1, std::string("Crystals: ") + flowNumText(ctx.saveValues[0]));
      livedbg::hit(39);
      ctx.dynTextRequest[2] = 1;
      ctx.dynTextDuration[2] = 0.0F;
      flowSetDynText(ctx, 2, std::string("Deaths: ") + flowNumText((float)flowInt[0]));
      livedbg::hit(40);
      ctx.dynTextRequest[3] = 1;
      ctx.dynTextDuration[3] = 0.0F;
      flowSetDynText(ctx, 3, std::string("Checkpoint: ") + std::string(&ctx.saveTexts[0 * SAVE_TEXT_LEN]));
    }
  }

 public:
  // Time machine (docs/time-machine.md): this graph's own
  // state - armed Delays, edge latches, latched outputs.
  FlowGraphScript_0_13() { g_time_FlowGraphScript_0_13 = this; }
  static const unsigned int kTimeBytes = 5;
  void timeCapture(unsigned char* p) const {
    memcpy(p + 0, &frame, 4);
    p[4] = started ? 1 : 0;
  }
  void timeRestore(const unsigned char* p) {
    memcpy(&frame, p + 0, 4);
    started = p[4] != 0;
  }

 private:
  unsigned int generation = 0;
  int frame = 0;
  bool started = false;
};

